# ******************************************************************************************************************** #
# *** CLASS SURVEY 1
# ******************************************************************************************************************** #
class p2_Survey1(Page):

    # form model and form fields
    # ----------------------------------------------------------------------------------------------------------------
    form_model = 'player'
    form_fields = [
        'risk_gen',
        'time_gen'
    ]

    # variables for template
    # ----------------------------------------------------------------------------------------------------------------
    def vars_for_template(self):

        # specify info for progress bar
        # ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
        total = 5
        page = 1
        progress = page / total * 100

        return {
            'page':         page,
            'total':        total,
            'progress':     progress,
        }


